#!/usr/bin/env python3
"""
Verifier for daylighting_controls_perimeter_zones task.

Checks:
1. Simulation ran during the session (anti-gaming).
2. Four specific 2nd-floor perimeter spaces have DAYLIGHTING = YES.
3. Those spaces have correctly configured DAYLGHT-CTRL parameters:
   - LIGHT-CTRL-TYPE = CONTINUOUS
   - LIGHT-SET-POINT = 50
   - MIN-POWER-FRAC = 0.30
   - MIN-LIGHT-FRAC = 0.20
"""

import json
import os
import tempfile
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Path to the result file generated by the export script inside the container/VM
RESULT_PATH_WIN = "C:\\Users\\Docker\\daylighting_task_result.json"

def verify_daylighting_controls(traj, env_info, task_info):
    """
    Verify that daylighting controls were correctly applied to perimeter zones.
    """
    copy_from_env = env_info.get('copy_from_env')
    if not copy_from_env:
        return {"passed": False, "score": 0, "feedback": "Copy function not available"}

    # Load expected values from metadata
    metadata = task_info.get('metadata', {})
    expected_params = metadata.get('expected_parameters', {})
    target_spaces = metadata.get('target_spaces', [])

    exp_type = expected_params.get("LIGHT-CTRL-TYPE", "CONTINUOUS")
    exp_setpoint = float(expected_params.get("LIGHT-SET-POINT", 50))
    exp_min_power = float(expected_params.get("MIN-POWER-FRAC", 0.30))
    exp_min_light = float(expected_params.get("MIN-LIGHT-FRAC", 0.20))

    # Retrieve result file
    temp_file = tempfile.NamedTemporaryFile(delete=False, suffix='.json')
    try:
        # Note: copy_from_env handles the path translation if needed, assume standard path
        copy_from_env(RESULT_PATH_WIN, temp_file.name)
        with open(temp_file.name, 'r', encoding='utf-8-sig') as f:
            result = json.load(f)
    except Exception as e:
        return {
            "passed": False, 
            "score": 0, 
            "feedback": f"Failed to retrieve or parse task result: {str(e)}"
        }
    finally:
        if os.path.exists(temp_file.name):
            os.unlink(temp_file.name)

    score = 0
    feedback_parts = []
    
    # Criterion 1: Simulation ran (10 pts)
    if result.get('sim_file_is_new'):
        score += 10
        feedback_parts.append("Simulation ran successfully (+10)")
    elif result.get('sim_file_exists'):
        feedback_parts.append("Simulation output exists but is old (must run simulation)")
    else:
        feedback_parts.append("No simulation output found")

    # Evaluate each space
    spaces_data = result.get('spaces', {})
    
    # We expect 4 spaces. 90 points distributed among them (22.5 pts each)
    # Breakdown per space:
    # - Daylighting Enabled: 5 pts
    # - Control Type: 5 pts
    # - Setpoint: 5 pts
    # - Min Power: 4 pts
    # - Min Light: 3.5 pts
    
    spaces_passed = 0
    
    for space_name in target_spaces:
        data = spaces_data.get(space_name, {})
        space_score = 0
        space_feedback = []
        
        # 1. Daylighting Enabled
        if data.get('daylighting_enabled'):
            space_score += 5
            
            # 2. Control Type
            act_type = data.get('ctrl_type')
            if act_type and act_type.upper() == exp_type:
                space_score += 5
            else:
                space_feedback.append(f"Type: {act_type}")

            # 3. Setpoint (allow small tolerance)
            try:
                act_setpoint = float(data.get('setpoint', -1))
                if abs(act_setpoint - exp_setpoint) < 0.5:
                    space_score += 5
                else:
                    space_feedback.append(f"Setpoint: {act_setpoint}")
            except (ValueError, TypeError):
                space_feedback.append("Setpoint: Missing")

            # 4. Min Power
            try:
                act_power = float(data.get('min_power', -1))
                if abs(act_power - exp_min_power) < 0.02:
                    space_score += 4
                else:
                    space_feedback.append(f"MinPower: {act_power}")
            except (ValueError, TypeError):
                space_feedback.append("MinPower: Missing")

            # 5. Min Light
            try:
                act_light = float(data.get('min_light', -1))
                if abs(act_light - exp_min_light) < 0.02:
                    space_score += 3.5
                else:
                    space_feedback.append(f"MinLight: {act_light}")
            except (ValueError, TypeError):
                space_feedback.append("MinLight: Missing")
                
        else:
            space_feedback.append("Daylighting NOT enabled")

        score += space_score
        
        # Check if this space counts as "passed" (mostly correct)
        if space_score >= 15: 
            spaces_passed += 1

        if space_feedback:
            # Only add specific feedback if something was wrong
            short_name = space_name.replace("EL2 ", "").replace(" Perim Spc", "")
            feedback_parts.append(f"{short_name}: {', '.join(space_feedback)}")

    # Final Verification Logic
    # Pass if Score >= 60 AND Simulation Ran AND at least 2 spaces are substantially correct
    passed = (score >= 60) and result.get('sim_file_is_new', False) and (spaces_passed >= 2)

    return {
        "passed": passed,
        "score": min(score, 100),
        "feedback": " | ".join(feedback_parts)
    }